import{_ as a,o as e,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse('{"title":"使用WebAssembly编译C++到JS","description":"","frontmatter":{"title":"使用WebAssembly编译C++到JS","date":"2019-04-28 20:51","comments":true,"archives":2019,"tags":["WebAssembly"]},"headers":[],"relativePath":"posts/2019-04-28-webassmebly/index.md","filePath":"posts/2019/2019-04-28-webassmebly.md"}'),p={name:"posts/2019-04-28-webassmebly/index.md"};function r(o,s,t,c,i,b){return e(),n("div",null,[...s[0]||(s[0]=[l(`<p>实际项目开发中遇到了一些已经使用 C++ 实现的功能，需要在新的 Web 客户端使用。由于主要是数学和算法的计算，没有平台依赖性。所以需要一个成本最低的移植方式，显然 WebAssembly 是一个非常好的方式。现在官方的编译工具是<a href="https://github.com/emscripten-core/emscripten" target="_blank" rel="noreferrer">emscripten</a></p><h2 id="移植方式" tabindex="-1">移植方式 <a class="header-anchor" href="#移植方式" aria-label="Permalink to &quot;移植方式&quot;">​</a></h2><p>从 C++ 编译到 JS。官方提供了两种编译方式<a href="https://emscripten.org/docs/porting/connecting_cpp_and_javascript/embind.html" target="_blank" rel="noreferrer">embind</a>和<a href="https://emscripten.org/docs/porting/connecting_cpp_and_javascript/WebIDL-Binder.html" target="_blank" rel="noreferrer">WebIDL Binder</a>。这两种方式，一开始我也很困惑。不过现在也是有所了解了。向大家介绍一下如何选择。如果你的 C++ 项目中有很多高级数据结构要使用，例如 vector，map。那推荐使用 embind，如果你的项目主要是简单数据类型，例如数字，字符串，bool，都可以简单的映射到 JS，并且是用 class 封装的，那推荐使用 WebIDL Binder。</p><h2 id="封装处理" tabindex="-1">封装处理 <a class="header-anchor" href="#封装处理" aria-label="Permalink to &quot;封装处理&quot;">​</a></h2><p>由于 C++ 数据结构比 JS 复杂的多，很多时候没有直接暴露成 JS 函数。我们需要进行封装，例如 C++ 中的引用调用，可以改变传入的参数的值。但是编译成 JS 的话，就不会生效。所以这时候我们需要写 wrap 函数，封装这些引用调用的 C++ 函数，然后再单独写 get 函数，得到修改的值。</p><h2 id="webpack-打包" tabindex="-1">webpack 打包 <a class="header-anchor" href="#webpack-打包" aria-label="Permalink to &quot;webpack 打包&quot;">​</a></h2><p>官方的 demo 是使用 src 的方式来引入，并且暴露成 <code>Module</code> 的全局变量。但是现代化的 Web 项目都是使用 webpack 打包，并且自动化引入的。所以我们也不想为了 WebAssembly 搞特殊。接下来就讲述如何配置来引入。首先，使用 emscripten 输出 <code>mjs</code> 文件，这样才可以作为模块被导入。具体的编译参数可以参照<a href="https://emscripten.org/docs/tools_reference/emcc.html" target="_blank" rel="noreferrer">emcc</a>。 首先，wasm 格式并不能被 webpack 正确识别，我们需要添加 loader</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">{</span></span>
<span class="line"><span style="color:#6F42C1;">  test</span><span style="color:#24292E;">:</span><span style="color:#032F62;"> /</span><span style="color:#22863A;font-weight:bold;">\\.</span><span style="color:#032F62;">wasm</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#6F42C1;">  type</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;javascript/auto&#39;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#6F42C1;">  loader</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;file-loader&#39;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>然后在项目中，分别 import mjs 文件和 wasm 文件。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> lib </span><span style="color:#D73A49;">from</span><span style="color:#032F62;"> &#39;./wasm.mjs&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> libWasm </span><span style="color:#D73A49;">from</span><span style="color:#032F62;"> &#39;./wasm.wasm&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> module</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> lib</span><span style="color:#24292E;">({</span></span>
<span class="line"><span style="color:#6F42C1;">  locateFile</span><span style="color:#24292E;">(</span><span style="color:#E36209;">path</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">    if</span><span style="color:#24292E;"> (path.</span><span style="color:#6F42C1;">endsWith</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;.wasm&#39;</span><span style="color:#24292E;">)) {</span></span>
<span class="line"><span style="color:#D73A49;">      return</span><span style="color:#24292E;"> libWasm;</span></span>
<span class="line"><span style="color:#24292E;">    }</span></span>
<span class="line"><span style="color:#D73A49;">    return</span><span style="color:#24292E;"> path;</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>然后在调用的时候替换掉默认的<code>locateFile</code>函数，即可完美导入到我们的项目中。</p><h2 id="内存泄漏" tabindex="-1">内存泄漏 <a class="header-anchor" href="#内存泄漏" aria-label="Permalink to &quot;内存泄漏&quot;">​</a></h2><p>C++ 中有很多高级的数据结构，我们可以映射成 JS 对象，但是内存管理还是需要自己处理。所有我们声明的 WebAssembly 数据结构并且包括函数返回的数据结构，都需要手动调用 <code>delete</code> 方法来释放内存。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>编译 C++ 到 JS，不仅需要 JS 的知识，还需要 C++ 知识，我们需要先把所有需要的 C++ 文件，先全部编译到 LLVM bitcode（.o 文件）。这里编译 C++ 可以使用 GCC 的全部编译参数，推荐使用 O3 参数来优化代码。最后编译到 JS 文件的时候，需要按照 emscripten 的规范来书写胶水文件。</p><p>参考：</p><p><a href="https://gist.github.com/surma/b2705b6cca29357ebea1c9e6e15684cc" target="_blank" rel="noreferrer">webpack-emscripten-wasm</a></p>`,17)])])}const y=a(p,[["render",r]]);export{d as __pageData,y as default};
